import sys, os

def get_setuptools_version():
    """Get setuptools version using standard library only, without importing setuptools directly."""
    # Try to find setuptools by examining installed packages metadata
    # This is a reliable method that doesn't import setuptools
    import importlib
    import importlib.util

    try:
        spec = importlib.util.find_spec("setuptools")
        if spec is None:
            return None

        # Read the version from metadata
        # First try pkg_resources style (which setuptools provides)
        # But we want to avoid importing setuptools
        # Instead, look for dist-info or egg-info directories

        # Get the location of setuptools
        location = spec.submodule_search_locations[0] if spec.submodule_search_locations else None

        # Try to find version in METADATA files
        # setuptools typically has version in __init__.py
        import ast

        init_py = os.path.join(location, "__init__.py")
        if os.path.exists(init_py):
            with open(init_py, "r") as f:
                content = f.read()

            # Parse the __version__ attribute
            tree = ast.parse(content)
            for node in ast.walk(tree):
                if isinstance(node, ast.Assign):
                    for target in node.targets:
                        if isinstance(target, ast.Name) and target.id == "__version__":
                            if isinstance(node.value, ast.Str):
                                return node.value.s
                            elif isinstance(node.value, ast.Constant):
                                return node.value.value

        # Fallback: try to read from pkg_resources metadata
        # Look for setuptools dist-info
        for base in sys.path:
            setuptools_info = os.path.join(base, "setuptools-*.dist-info")
            if os.path.isdir(setuptools_info):
                # Find METADATA file
                for f_name in os.listdir(setuptools_info):
                    if f_name == "METADATA":
                        metadata_path = os.path.join(setuptools_info, f_name)
                        with open(metadata_path, "r") as f:
                            for line in f:
                                if line.startswith("Version:"):
                                    return line.split(":", 1)[1].strip()

            # Also check for egg-info
            setuptools_egg = os.path.join(base, "setuptools-*.egg-info")
            if os.path.isdir(setuptools_egg):
                pkgs_dir = os.path.join(setuptools_egg, "PKG-INFO")
                if os.path.exists(pkgs_dir):
                    with open(pkgs_dir, "r") as f:
                        for line in f:
                            if line.startswith("Version:"):
                                return line.split(":", 1)[1].strip()

        return None
    except Exception:
        return None

version = get_setuptools_version()
if version is not None:
    print('system setuptools', version)
else:
    print('system setuptools', '')

