# setuptools typically ships a version in its .dist-info or .egg-info directory.
# We can look for a metadata file or __init__.py in site-packages.

import os
import sys

def find_setuptools_version():
    # Try to find setuptools metadata in sys.path
    candidates = []
    for p in sys.path:
        if not p:
            p = '.'
        # Check for setuptools dist-info or egg-info
        # Look for directory named setuptools-*.dist-info or setuptools-*.egg-info
        try:
            entries = os.listdir(p)
        except (OSError, PermissionError):
            continue
        for e in entries:
            if e.startswith('setuptools-') and (e.endswith('.dist-info') or e.endswith('.egg-info')):
                version_str = e[len('setuptools-'):]
                if version_str.endswith('.dist-info'):
                    version_str = version_str[:-len('.dist-info')]
                elif version_str.endswith('.egg-info'):
                    version_str = version_str[:-len('.egg-info')]
                # The version string should be between 'setuptools-' and '.dist-info'/'.egg-info'
                # But there could be extra suffixes like py3
                # e.g., setuptools-45.2.0.dist-info -> 45.2.0
                # Actually the format is: setuptools-{version}.dist-info
                # So version is everything between 'setuptools-' and '.dist-info'
                candidates.append(version_str)
                break
        # Also check for a setuptools/__init__.py with __version__
        setuptools_dir = os.path.join(p, 'setuptools')
        if os.path.isdir(setuptools_dir):
            init_file = os.path.join(setuptools_dir, '__init__.py')
            if os.path.isfile(init_file):
                # Read __version__ from __init__.py
                try:
                    with open(init_file, 'r') as f:
                        content = f.read()
                    for line in content.splitlines():
                        if '__version__' in line and '=' in line:
                            # Extract the version string
                            parts = line.split('=', 1)
                            if len(parts) == 2:
                                val = parts[1].strip()
                                # Remove quotes
                                if val.startswith("'") and val.endswith("'"):
                                    val = val[1:-1]
                                elif val.startswith('"') and val.endswith('"'):
                                    val = val[1:-1]
                                # The value might be like "45.2.0" or something computed
                                # If it's a simple string literal, use it
                                if val and not any(c.isspace() for c in val):
                                    candidates.append(val)
                                    break
                except (OSError, UnicodeDecodeError):
                    pass
    if candidates:
        # Return the first one found (most specific path first in sys.path)
        return candidates[0]
    return None

version = find_setuptools_version()
if version is not None:
    print('system setuptools', version)
else:
    # Fallback: this should not happen if setuptools is installed
    print('system setuptools', '')

