# Simulate random.seed(1) and random.randrange(0, 10, 2)
# Python's random module uses Mersenne Twister (MT19937)

# We need to reproduce the exact behavior of random.seed(1); print(random.randrange(0, 10, 2))

# Let's manually implement the Mersenne Twister as used by Python's random module

class MersenneTwister:
    def __init__(self, seed):
        self.mt = [0] * 624
        self.index = 624
        self.seed(seed)

    def seed(self, seed):
        self.mt[0] = seed & 0xffffffff
        for i in range(1, 624):
            self.mt[i] = (1812433253 * (self.mt[i-1] ^ (self.mt[i-1] >> 30)) + i) & 0xffffffff
        self.index = 624

