def shorten(text, width, placeholder="...", **kwargs):
    if len(text) <= width:
        return text
    # Find the cut point so that text[:cut] + placeholder fits within width
    # We want the longest prefix that ends at a word boundary and fits
    trunc_len = width - len(placeholder)
    # Check if trunc_len is at a word boundary
    if trunc_len == 0:
        return placeholder
    if text[trunc_len] == ' ' or text[trunc_len - 1] == ' ':
        # cut at trunc_len
        result = text[:trunc_len] + placeholder
        return result.strip()
    # Otherwise, find the last space before trunc_len
    last_space = text.rfind(' ', 0, trunc_len)
    if last_space == -1:
        result = text[:trunc_len] + placeholder
        return result.strip()
    else:
        result = text[:last_space] + placeholder
        return result.strip()

