    lines = text.split("\n")

    # Determine margin: minimum number of leading spaces/tabs on any non-blank line
    # But first, we need to handle the case where the text has no content
    if not lines:
        return text

    # Find the margin based on the first non-blank line
    margin = None
    for line in lines:
        if line.strip() != "":
            # Find leading whitespace
            i = 0
            while i < len(line) and (line[i] == ' ' or line[i] == '\t'):
                i += 1
            if i > 0:
                ws = line[:i]
                if margin is None:
                    margin = ws
                else:
                    # Find common prefix
