                    j = 0
                    while j < minlen and margin[j] == ws[j]:
                        j += 1
                    margin = margin[:j]
            break

    if margin is None:
        return text

    # Remove the margin from each line
    result_lines = []
    for line in lines:
        if line.strip() == "":
            result_lines.append(line)
        else:
            if line.startswith(margin):
                result_lines.append(line[len(margin):])
            else:
                result_lines.append(line)

