            i += 1
            # Remaining args are positional
            if i < len(args):
                word = args[i]
                i += 1
        else:
            # Positional argument
            if word is None:
                word = arg
            i += 1

    if word is None:
        # Missing required positional argument
        sys.exit(1)

    sys.stdout.write(word * n + "\n")

