def sub_basic(pattern, replacement, text):
    i = 0
    result = []
    while i < len(text):
        m = pattern(text, i)
        if m is not None:
            end = m[0]
            groups = m[1]
            rep = replacement(groups)
            result.append(rep)
            i = end
        else:
            result.append(text[i])
            i += 1
    return ''.join(result)

def pattern1(text, i):
    if i >= len(text):
        return None
    c = text[i]
    if not (c.isalnum() or c == '_'):
        return None
    start = i
    j = i
    while j < len(text) and (text[j].isalnum() or text[j] == '_'):
        j += 1
    local1 = text[start:j]
    k = j
    if k >= len(text) or text[k] != '@':
        return None
    k += 1
    if k >= len(text):
        return None
    c2 = text[k]
    if not (c2.isalnum() or c2 == '_'):
        return None
    start2 = k
    j2 = k
    while j2 < len(text) and (text[j2].isalnum() or text[j2] == '_'):
        j2 += 1
    local2 = text[start2:j2]
    end = j2
    groups = [local1, local2]
    return (end, groups)

def replacement1(groups):
    return groups[1] + ':' + groups[0]

def pattern2(text, i):
    if i >= len(text):
        return None
    c = text[i]
    if not c.isdigit():
        return None
    start = i
    j = i
    while j < len(text) and text[j].isdigit():
        j += 1
    local1 = text[start:j]
    end = j
    groups = [local1]
    return (end, groups)

def replacement2(groups):
    return '[' + groups[0] + ']'

