    # Parse each line as a Python literal
    corpus_lines = [line for line in corpus_py.strip().split('\n') if line]
    probe_lines = [line for line in probe_py.strip().split('\n') if line]

    if len(corpus_lines) != len(probe_lines):
        return False

    corpus_sets = []
    probe_sets = []

    for line in corpus_lines:
        obj = eval(line, {"__builtins__": {}}, {"set": set, "dict": dict, "list": list, "tuple": tuple})
        corpus_sets.append(obj)

    for line in probe_lines:
        obj = eval(line, {"__builtins__": {}}, {"set": set, "dict": dict, "list": list, "tuple": tuple})
        probe_sets.append(obj)

    # Compare: each corpus_set[i] should equal probe_set[i] as sets (order doesn't matter)
    for c, p in zip(corpus_sets, probe_sets):
        if isinstance(c, (set, frozenset)) and isinstance(p, (set, frozenset)):
            if c != p:
                return False
        elif isinstance(c, (list, tuple)) and isinstance(p, (list, tuple)):
            # For lists/tuples, order matters, but the problem says "only set order differs"
            # So these should be equal
            if c != p:
                return False
        else:
            if c != p:
                return False

    return True


