import sys
import re

def extract_with_tails(cmd):
    # Extract python-related arguments with tails
    # This function extracts the code from python invocations
    # and any tail arguments (arguments after the code/command)

    # Find python invocations
    # Pattern to find python3 or python commands
    result = []

    # First, let's try to parse the command line
    # We need to handle quotes properly

    tokens = _tokenize(cmd)

    # Find all python invocations
    i = 0
    while i < len(tokens):
        token = tokens[i]
        if token in ('python', 'python3', 'python2') or token.endswith('/python') or token.endswith('/python3') or token.endswith('/python2'):
            j = i + 1
            # Skip flags like -c, -m, etc.
            code_arg = None
            tail_start = None

            # Check for -c flag
            while j < len(tokens) and tokens[j].startswith('-') and tokens[j] != '-c' and tokens[j] != '-m' and tokens[j] not in ('--help', '--version', '--interactive', '--insite'):
                # Could be a flag with value or standalone flag
                # Common flags: -u, -O, -B, -S, -I, -E, -s, -W
                if tokens[j] in ('-W',):
                    j += 2  # -W takes an argument
                else:
                    j += 1

            if j < len(tokens) and tokens[j] == '-c':
                if j + 1 < len(tokens):
                    code_arg = tokens[j + 1]
                    j += 2
            elif j < len(tokens) and tokens[j] == '-m':
                if j + 1 < len(tokens):
                    code_arg = tokens[j + 1]
                    j += 2
            else:
                # It's a script file
                if j < len(tokens):
                    code_arg = tokens[j]
                    j += 1

            # Everything after is tail
            tail = tokens[j:]

            # Build the extracted string
            parts = [token]
            # Include flags between the command and the code
            # Actually, let's just include the code and tail
            # The "with_tails" likely means it includes trailing arguments

            # Looking at the pattern, I think extract_with_tails returns
            # a list of (code, tails) tuples or just the extracted parts
            # Let me reconsider

            # I'll return the code and tail as a tuple or combined string
            result.append((code_arg, tail))

        i += 1

    return result

def _tokenize(cmd):
    """Simple tokenizer that handles quotes."""
    tokens = []
    current = []
    in_single = False
    in_double = False
    i = 0
    while i < len(cmd):
        c = cmd[i]
        if in_single:
            if c == "'":
                in_single = False
            else:
                current.append(c)
        elif in_double:
            if c == '"':
                in_double = False
            elif c == '\\' and i + 1 < len(cmd) and cmd[i+1] in ('"', '\\', '$', '`'):
                current.append(cmd[i+1])
                i += 1
            else:
                current.append(c)
        else:
            if c == "'":
                in_single = True
            elif c == '"':
                in_double = True
            elif c in (' ', '\t'):
                if current:
                    tokens.append(''.join(current))
                    current = []
            elif c == '\\' and i + 1 < len(cmd):
                current.append(cmd[i+1])
                i += 1
            else:
                current.append(c)
        i += 1
    if current:
        tokens.append(''.join(current))
    return tokens

def looks_pythonish(s):
    """Check if a string looks like it might be Python-related."""
    if not s:
        return False
    s_lower = s.lower()
    return ('.py' in s_lower or 'python' in s_lower or 'py ' in s_lower)

def main():
    tests = [
        'cat > x.py <<"EOF"\nprint(1)\nEOF\npython3 x.py',
        'python3 -c "print(1)" a b',
        'PYTHONPATH=. python3 -c "print(1)"',
        'python3 -c "print(1)" && python3 -c "print(2)"',
    ]

    for t in tests:
        print(repr(t), '->', extract_with_tails(t))

    print(looks_pythonish('cat > x.py <<"EOF"'))

if __name__ == '__main__':
    main()

