def _getattr(obj, name, *defargs):
    if len(defargs) == 0:
        if not hasattr(obj, name):
            raise AttributeError(name)
        return getattr2(obj, name)
    else:
        if hasattr(obj, name):
            return getattr2(obj, name)
        return defargs[0]


