import sys

def format_int(n, width, prec, plus, zero):
    s = str(abs(n))
    if len(s) < prec:
        s = s.zfill(prec)
    if n < 0:
        s = '-' + s
    elif plus:
        s = '+' + s
    total = len(s)
    if total < width:
        pad = width - total
        if zero:
            neg = s.startswith('-') or s.startswith('+')
            if neg:
                s = s[0] + '0' * pad + s[1:]
            else:
                s = '0' * pad + s
        else:
            s = s.rjust(width)
    return s

def format_str(st, width, prec, left):
    if prec is not None:
        st = st[:prec]
    if width is not None and len(st) < width:
        if left:
            st = st.ljust(width)
        else:
            st = st.rjust(width)
    return st

