def _percent_format(format_string, value):
    # Parse the percent format string and apply it manually
    # Handle: %<flag><width>[.precision]<type>
    # Where type is one of: d, i, u, x, X, o, c, s, %

    if not format_string.startswith('%'):
        return format_string

    rest = format_string[1:]

    # Parse flags
    flags = set()
    idx = 0
    while idx < len(rest) and rest[idx] in '-+0 #':
        flags.add(rest[idx])
        idx += 1

    # Parse width
    width = 0
    has_width = False
    while idx < len(rest) and rest[idx].isdigit():
        width = width * 10 + int(rest[idx])
        has_width = True
        idx += 1

    # Parse precision
    precision = None
    has_precision = False
    if idx < len(rest) and rest[idx] == '.':
        idx += 1
        precision = 0
        has_precision = True
        while idx < len(rest) and rest[idx].isdigit():
            precision = precision * 10 + int(rest[idx])
            idx += 1

    # Parse conversion type
    if idx >= len(rest):
        return format_string
    conv_type = rest[idx]

    # The remainder after the conversion type should be empty
    # (We assume well-formed format strings)

    if conv_type == 'd' or conv_type == 'i' or conv_type == 'u':
        # Integer conversions
        if not isinstance(value, int):
            raise TypeError("an integer is required")

        v = value
        negative = False
        if v < 0:
            negative = True
            v = -v

        s = str(v)

        if conv_type == 'x':
            pass
        elif conv_type == 'X':
            pass
        elif conv_type == 'o':
            pass
        else:
            # d, i, u are all decimal
            pass

        # Apply precision as minimum number of digits
        if has_precision and precision > 0:
            s = s.zfill(precision)

        # Apply sign
        if negative:
            s = '-' + s
        elif '+' in flags and conv_type in ('d', 'i'):
            s = '+' + s
        elif ' ' in flags and conv_type in ('d', 'i'):
            s = ' ' + s

        # Apply width
        if has_width and width > 0:
            pad_chars = width - len(s)
            if pad_chars > 0:
                if '-' in flags:
                    s = s.ljust(width)
                elif '0' in flags:
                    # Zero pad, but keep sign in front
                    if negative or ('+' in flags) or (' ' in flags):
                        sign = s[0]
                        num_part = s[1:]
                        s = sign + num_part.zfill(pad_chars)
                    else:
                        s = s.zfill(width)
                else:
                    s = s.rjust(width)

        return s

    elif conv_type == 'x' or conv_type == 'X' or conv_type == 'o':
        # Hex, octal conversions
        if not isinstance(value, int):
            raise TypeError("an integer is required")

        v = value
        negative = v < 0
        v = abs(v)

        if conv_type == 'x':
            s = format(v, 'x')
        elif conv_type == 'X':
            s = format(v, 'X')
        elif conv_type == 'o':
            s = format(v, 'o')

        # Apply precision as minimum number of digits
        if has_precision and precision > 0:
            s = s.zfill(precision)

        # Apply sign
        if negative:
            s = '-' + s
        elif '+' in flags:
            s = '+' + s
        elif ' ' in flags:
            s = ' ' + s

        # Apply width
        if has_width and width > 0:
            pad_chars = width - len(s)
            if pad_chars > 0:
                if '-' in flags:
                    s = s.ljust(width)
                elif '0' in flags:
                    if negative or ('+' in flags) or (' ' in flags):
                        sign = s[0]
                        num_part = s[1:]
                        s = sign + num_part.zfill(pad_chars)
                    else:
                        s = s.zfill(width)
                else:
                    s = s.rjust(width)

        return s

    elif conv_type == 'c':
        # Character conversion
        if not isinstance(value, int):
            raise TypeError("an integer is required")
        if value < 0 or value > 255:
            raise ValueError("chr() arg not in range(0,256)")
        s = chr(value)

        # Precision doesn't apply to 'c'
        # Apply width
        if has_width and width > 0:
            pad_chars = width - len(s)
            if pad_chars > 0:
                if '-' in flags:
                    s = s.ljust(width)
                elif '0' in flags:
                    s = s.zfill(width)
                else:
                    s = s.rjust(width)

        return s

    elif conv_type == 's':
        # String conversion
        s = str(value)

        # Apply precision as max length
        if has_precision and precision is not None:
            s = s[:precision]

        # Apply width
        if has_width and width > 0:
            pad_chars = width - len(s)
            if pad_chars > 0:
                if '-' in flags:
                    s = s.ljust(width)
                else:
                    s = s.rjust(width)

        return s

    else:
        raise ValueError("unknown conversion type")


