import os, sys

def fmt_percent(s, v):
    # Parse a C-style percent format string %flags.width.precision.type
    # and reproduce it using Python's str.format / int() for the subset
    # of formats the original program exercises.
    assert s[0] == '%'
    rest = s[1:]
    flags = ''
    body = rest
    while body and body[0] in '+- 0':
        flags += body[0]
        body = body[1:]
    width = None
    precision = None
    i = 0
    while i < len(body) and body[i].isdigit():
        i += 1
    if i > 0:
        width = int(body[:i])
        body = body[i:]
    if body.startswith('.'):
        body = body[1:]
        j = 0
        while j < len(body) and body[j].isdigit():
            j += 1
        precision = int(body[:j]) if j > 0 else 0
        body = body[j:]
    conv = body[0]
    assert len(body) == 1
    minus = '-' in flags
    plus = '+' in flags
    zero = '0' in flags
    space = ' ' in flags
    pad_char = '0' if zero and width is not None else ' '

    def place(s_val, w):
        if w is None:
            return s_val
        pad = w - len(s_val)
        if pad <= 0:
            return s_val
        if minus:
            return s_val + ' ' * pad
        return ' ' * pad + s_val

    if conv in 'd':
        n = int(v)
        sign = ''
        if plus or space:
            if n >= 0:
                sign = '+' if plus else ' '
        m = abs(n)
        d = str(m)
        if precision is not None and precision > len(d):
            d = '0' * (precision - len(d)) + d
        s_val = sign + d
        if zero and width is not None and sign:
            # zero-pad between the sign and the digits
            inner = d
            target = width - len(sign)
            if len(inner) < target:
                inner = '0' * (target - len(inner)) + inner
            s_val = sign + inner
        else:
            s_val = place(s_val, width)
        return s_val
    if conv in 'x':
        n = int(v)
        s_val = format(n, 'x')
        return place(s_val, width)
    if conv in 'X':
        n = int(v)
        s_val = format(n, 'X')
        return place(s_val, width)
    if conv in 'o':
        n = int(v)
        s_val = format(n, 'o')
        return place(s_val, width)
    if conv in 'u':
        n = int(v)
        s_val = str(n)
        return place(s_val, width)
    if conv in 'c':
        n = int(v)
        s_val = chr(n)
        return place(s_val, width)
    if conv in 's':
        sval = str(v)
        if precision is not None and len(sval) > precision:
            sval = sval[:precision]
        return place(sval, width)
    raise AssertionError('unhandled')

