from decimal import Decimal

def intfmt_d(value, width=0, prec=0, fill=' ', left=False, zero_fill=False, plus=False):
    sign = ''
    if value < 0:
        sign = '-'
        value = -value
    elif plus:
        sign = '+'
    digits = str(value)
    if prec:
        digits = digits.zfill(prec)
    need = len(digits) + len(sign)
    if not zero_fill:
        padding = width - need
        if left:
            result = sign + digits + ' ' * (padding if padding > 0 else 0)
        else:
            result = ' ' * (padding if padding > 0 else 0) + sign + digits
    else:
        digits = digits.zfill(prec)
        padding = width - len(digits) - len(sign)
        if left:
            result = sign + digits + '0' * (padding if padding > 0 else 0)
        else:
            result = '0' * (padding if padding > 0 else 0) + sign + digits
    return result

def intfmt_x(value, prec=0, upper=False):
    if value < 0:
        sign = '-'
        value = -value
    else:
        sign = ''
    digits = format(value, 'x') if not upper else format(value, 'X')
    if prec:
        digits = digits.zfill(prec)
    return sign + digits

def intfmt_o(value, prec=0):
    if value < 0:
        sign = '-'
        value = -value
    else:
        sign = ''
    digits = format(value, 'o')
    if prec:
        digits = digits.zfill(prec)
    return sign + digits

def handle_percent(s, v):
    import re
    m = re.match(r'%([-+#0]*)(\d*)(\.\d+|\.)([diouxXoc s])', s)
    if not m:
        raise Exception("unhandled format: " + s)
    flags = m.group(1)
    width = int(m.group(2)) if m.group(2) else 0
    pres_str = m.group(3)
    conv = m.group(4)
    plus = '+' in flags
    left = '-' in flags
    zero_fill = '0' in flags
    if pres_str and pres_str != '.':
        prec = int(pres_str[1:])
    elif pres_str == '.':
        prec = 0
    else:
        prec = None

    if conv == 'd':
        return intfmt_d(v, width, prec if prec is not None else 0, fill=' ', left=left, zero_fill=zero_fill, plus=plus)
    elif conv == 'i':
        return intfmt_d(v, width, prec if prec is not None else 0, fill=' ', left=left, zero_fill=zero_fill, plus=plus)
    elif conv == 'u':
        if v < 0:
            v = v + (1 << 64)
        return intfmt_d(v, width, prec if prec is not None else 0, fill=' ', left=left, zero_fill=zero_fill, plus=plus)
    elif conv == 'x':
        if v < 0:
            v = v + (1 << 64)
        return intfmt_x(v, prec if prec is not None else 0, upper=False)
    elif conv == 'X':
        if v < 0:
            v = v + (1 << 64)
        return intfmt_x(v, prec if prec is not None else 0, upper=True)
    elif conv == 'o':
        if v < 0:
            v = v + (1 << 64)
        return intfmt_o(v, prec if prec is not None else 0)
    elif conv == 'c':
        return chr(v)
    elif conv == 's':
        text = str(v)
        if prec is not None:
            text = text[:prec]
        if left:
            return text + ' ' * (width - len(text) if width > len(text) else 0)
        else:
            return ' ' * (width - len(text) if width > len(text) else 0) + text
    else:
        raise Exception("unknown conv")

