            else:
                # left or right pad with spaces
                if '-' in spec[0:3]:  # check for left-align
                    # Actually we need to track this properly
                    pass
                # For simplicity, check original spec for '-'
                if '-' in spec and not has_zero_pad:
                    result = sign + digits + ' ' * pad
                else:
                    result = ' ' * pad + sign + digits
        else:
            result = sign + digits

        return result
    elif conv in 'xXo':
        # Hex/octal
        if conv == 'x':
            if v_int < 0:
                result = '-' + format(-v_int, 'x')
            else:
                result = format(v_int, 'x')
        elif conv == 'X':
            if v_int < 0:
                result = '-' + format(-v_int, 'X')
            else:
                result = format(v_int, 'X')
        else:  # 'o'
            if v_int < 0:
                result = '-' + format(-v_int, 'o')
            else:
                result = format(v_int, 'o')

        if prec > 0 and len(result.lstrip('-')) < prec:
            sign = result[0] if result[0] == '-' else ''
            digits = result[1:] if result[0] == '-' else result
            digits = '0' * (prec - len(digits)) + digits
            result = sign + digits

        if width_val > 0 and len(result) < width_val:
            pad = width_val - len(result)
            if has_zero_pad:
                if result[0] == '-':
                    result = '-' + '0' * pad + result[1:]
                else:
                    result = '0' * pad + result
            else:
                result = ' ' * pad + result

        return result
    elif conv == 'c':
        return chr(v_int)
    elif conv == 's':
        s = str(v)
        if prec > 0 and len(s) > prec:
            s = s[:prec]
        if width_val > 0 and len(s) < width_val:
            s = ' ' * (width_val - len(s)) + s
        return s

    return str(v)


def main():
    results = []
    test_cases = [
        ('%.2d', -1),
        ('%.2i', -1),
        ('%.2u', -1),
        ('%.2x', -1),
        ('%.2X', -1),
        ('%.2o', -1),
        ('%.2c', 65),
        ('%.2s', 'a'),
        ('%.0d', -1),
        ('%.d', -1),
        ('%5.2d', -1),
        ('%-5.2d', -1),
        ('%05.2d', -1),
        ('%+.2d', -1),
        ('%05.7d', -1),
    ]

    for spec, v in test_cases:
        try:
            r = repr(emulate_percent(spec, v))
        except Exception as e:
            r = '%s: %s' % (type(e).__name__, str(e)[:40])
        results.append('  %-8s %% %-4r -> %s' % (spec, v, r))

    for line in results:
        print(line)

main()

