import json
import datetime

def _recent_capture_note(path: str) -> str:
    try:
        with open(path, "r") as f:
            lines = f.readlines()
    except (OSError, IOError):
        return "no capture log"

    recent_notes = []
    for line in lines:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue
        if obj.get("kind") != "note":
            continue
        ts = obj.get("ts")
        if not ts:
            continue
        try:
            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except (ValueError, TypeError):
            continue
        recent_notes.append((dt, obj))

    if not recent_notes:
        return "no recent capture"

    # Get the most recent note
    recent_notes.sort(key=lambda x: x[0], reverse=True)
    most_recent = recent_notes[0][1]
    detail = most_recent.get("detail", "")
    return detail

