import os, subprocess, sys, tempfile, threading, time, socket, shutil, atexit

_SERVER_ID = os.getpid()


class Server:
    def __init__(self, sock_path):
        self.path = sock_path
        self._srv = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        self._srv.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._closed = False

    def warm(self):
        # Nothing to pre-spawn for a per-call subprocess backend.
        return None

    def open(self):
        try:
            os.unlink(self.path)
        except OSError:
            pass
        self._srv.bind(self.path)
        self._srv.listen(8)

    def serve_forever(self):
        try:
            while not self._closed:
                try:
                    conn, _ = self._srv.accept()
                except OSError:
                    break
                thread = threading.Thread(target=self._handle, args=(conn,), daemon=True)
                thread.start()
        except Exception:
            pass

    def _handle(self, conn):
        try:
            conn.settimeout(300)
            buf = b""
            while b"\n" not in buf:
                chunk = conn.recv(65536)
                if not chunk:
                    return
                buf += chunk
            line, _, rest = buf.partition(b"\n")
            program = line.decode("utf-8")
            cwd = rest.decode("utf-8") or None
            if not cwd or not os.path.isdir(cwd):
                cwd = os.getcwd()
            try:
                r = subprocess.run(
                    [sys.executable, "-c", program],
                    capture_output=True,
                    text=True,
                    cwd=cwd,
                    stdin=subprocess.DEVNULL,
                )
                rc = r.returncode
                err = r.stderr
            except Exception as e:
                rc = 1
                err = "%s: %s\n" % (type(e).__name__, e)
            data = str(rc).encode("utf-8") + b"\n" + err.encode("utf-8")
            conn.sendall(data)
        except Exception:
            pass
        finally:
            try:
                conn.close()
            except Exception:
                pass

    def shutdown(self):
        try:
            self._closed = True
            self._srv.close()
        except Exception:
            pass


class Client:
    def __init__(self, sock_path):
        self.path = sock_path
        self._sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        self._sock.connect(self.path)
        self._sock.settimeout(300)

    def run(self, program, cwd=None):
        cwd = cwd or os.getcwd()
        payload = (program + "\n" + cwd).encode("utf-8")
        self._sock.sendall(payload)
        buf = b""
        while True:
            chunk = self._sock.recv(65536)
            if not chunk:
                break
            buf += chunk
        line, _, rest = buf.partition(b"\n")
        rc = int(line.decode("utf-8"))
        err = rest.decode("utf-8")
        return {"returncode": rc, "stdout": "", "stderr": err}

    def shutdown(self):
        try:
            self._sock.close()
        except Exception:
            pass


def main():
    d = tempfile.mkdtemp()
    atexit.register(shutil.rmtree, d, ignore_errors=True)
    sock = os.path.join(d, "p.sock")
    srv = Server(sock)
    srv.warm()
    srv.open()
    threading.Thread(target=srv.serve_forever, daemon=True).start()
    time.sleep(0.2)
    c = Client(sock)
    cwd = tempfile.mkdtemp()
    progs = [
        "raise ValueError('boom')",
        "def f():\n    1/0\nf()",
        "import sys; sys.exit('msg')",
    ]
    for p in progs:
        ref = subprocess.run(
            [sys.executable, "-c", p],
            capture_output=True,
            text=True,
            cwd=cwd,
            stdin=subprocess.DEVNULL,
        )
        got = c.run(p, cwd=cwd)
        print("=" * 66)
        print("PROG:", p.replace("\n", "; "))
        print("CPY rc=%s err=%r" % (ref.returncode, ref.stderr))
        print("POOL rc=%s err=%r" % (got["returncode"], got["stderr"]))
        print("IDENTICAL:", ref.returncode == got["returncode"] and ref.stderr == got["stderr"])
    c.shutdown()
    srv.shutdown()


if __name__ == "__main__":
    main()
    sys.exit(0)

