import os
import sys
import json
from collections import deque


def scan_jsonl_files(base_dirs, line_handler):
    # Standard BFS, sorted so it's reproducible (was originally glob-order)
    # Actually the original was glob-order which was NOT reproducible, so
    # the new behavior is well-defined
    queue = deque()
    for bd in base_dirs:
        queue.append((bd, False))
    while queue:
        node, is_dir = queue.popleft()
        if is_dir:
            if not os.path.isdir(node):
                continue
            try:
                entries = os.listdir(node)
            except OSError:
                continue
            sorted_entries = sorted(entries)
            for name in sorted_entries:
                full = os.path.join(node, name)
                if os.path.islink(full):
                    # skip symlinks to avoid cycles
                    continue
                if os.path.isdir(full):
                    queue.append((full, True))
                elif os.path.isfile(full):
                    queue.append((full, False))
        else:
            if node.endswith('.jsonl'):
                try:
                    with open(node, 'r') as fh:
                        for line in fh:
                            line_handler(line)
                except OSError:
                    pass


def main():
    # original glob: ~/.claude/projects/*/*.jsonl
    # base = ~/.claude/projects/* (one level)
    base = os.path.expanduser('~/.claude/projects')

    # Build list of base level dirs (the * part)
    base_level_dirs = []
    if os.path.isdir(base):
        try:
            entries = os.listdir(base)
        except OSError:
            entries = []
        for name in entries:
            full = os.path.join(base, name)
            if os.path.isdir(full) and not os.path.islink(full):
                base_level_dirs.append(full)
    # Sort for reproducibility (this is a change but necessary)
    base_level_dirs = sorted(base_level_dirs)

    tot = 0
    side = 0
    tsex = None
    tu = 0
    withid = 0

    def line_handler(line):
        nonlocal tot, side, tsex, tu, withid
        line = line.strip()
        if not line:
            return
        try:
            ev = json.loads(line)
        except Exception:
            return
        tot += 1
        if ev.get('isSidechain'):
            side += 1
        if tsex is None and ev.get('timestamp'):
            tsex = ev['timestamp']
        m = ev.get('message')
        if isinstance(m, dict) and isinstance(m.get('content'), list):
            for b in m['content']:
                if isinstance(b, dict) and b.get('type') == 'tool_use':
                    tu += 1
                    if b.get('id'):
                        withid += 1

    scan_jsonl_files(base_level_dirs, line_handler)

    sys.stdout.write('records %d sidechain %d tool_use blocks %d with id %d\n' % (
        tot, side, tu, withid))
    sys.stdout.write('timestamp example: %s\n' % (tsex,))


if __name__ == '__main__':
    main()

