def walk_tree(base, results):
    stack = [base]
    while stack:
        d = stack.pop()
        try:
            entries = os.listdir(d)
        except OSError:
            continue
        for name in entries:
            full = os.path.join(d, name)
            if os.path.isdir(full):
                stack.append(full)
            elif os.path.isfile(full) and name.endswith(".jsonl"):
                results.append(full)

