def loads(s):
    d = {}
    stack = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == '"':
            i += 1
            buf = []
            while i < n:
                c = s[i]
                if c == '\\':
                    if i + 1 < n:
                        nc = s[i + 1]
                        if nc == '"':
                            buf.append('"')
                            i += 2
                        elif nc == '\\':
                            buf.append('\\')
                            i += 2
                        elif nc == '/':
                            buf.append('/')
                            i += 2
                        elif nc == 'b':
                            buf.append('\b')
                            i += 2
                        elif nc == 'f':
                            buf.append('\f')
                            i += 2
                        elif nc == 'n':
                            buf.append('\n')
                            i += 2
                        elif nc == 'r':
                            buf.append('\r')
                            i += 2
                        elif nc == 't':
                            buf.append('\t')
                            i += 2
                        elif nc == 'u':
                            if i + 5 < n:
                                hexs = s[i + 2:i + 6]
