def safe_repr(s):
    # This replaces repr(s) for the specific strings in the list
    # We need to handle:
    # - Regular ASCII printable chars
    # - Quote characters (single/double)
    # - Special chars like \n, \t, \r, etc.
    # - Non-ASCII characters (which need to be escaped)

    # repr in Python adds quotes and escapes certain characters
    # Let's build it manually

    result = '"'
    for c in s:
        code = ord(c)
        if code < 128:
            # ASCII
            if c == '"':
                result += '\\"'
            elif c == '\\':
                result += '\\\\'
            elif c == '\n':
                result += '\\n'
            elif c == '\t':
                result += '\\t'
            elif c == '\r':
                result += '\\r'
            elif c == '\0':
                result += '\\0'
            elif c == '\x0b':
                result += '\\v'
            elif c == '\x0c':
                result += '\\f'
            elif c == '\x1b':
                result += '\\x1b'
            elif 32 <= code < 127:
                result += c
            else:
                # Control characters
                result += '\\x{:02x}'.format(code)
        else:
            # Non-ASCII: use \uXXXX or \UXXXXXXXX
            if code <= 0xFFFF:
                result += '\\u{:04x}'.format(code)
            else:
                result += '\\U{:08x}'.format(code)
    result += '"'
    return result

