def make_repr(s):
    if any(ord(c) > 126 for c in s):
        # Determine if the string is printable
        printable = True
        for c in s:
            o = ord(c)
            if o < 32 or o == 127:
                printable = False
                break
        if printable:
            # Build repr using Python string literal rules
            # We need to mimic what repr() does for a printable unicode string
            # For printable strings, repr() returns the string enclosed in quotes
            # with appropriate escaping
            result = []
            result.append('"')
            for c in s:
                o = ord(c)
                if c == '\\':
                    result.append('\\\\')
                elif c == '"':
                    result.append('\\"')
                elif c == '\t':
                    result.append('\\t')
                elif c == '\n':
                    result.append('\\n')
                elif c == '\r':
                    result.append('\\r')
                elif c == '\b':
                    result.append('\\b')
                elif c == '\f':
                    result.append('\\f')
                elif c == '\v':
                    result.append('\\v')
                elif o < 32:
                    if o == 1:
                        result.append('\\x01')
                    elif o == 2:
                        result.append('\\x02')
                    elif o == 3:
                        result.append('\\x03')
                    elif o == 4:
                        result.append('\\x04')
                    elif o == 5:
