def ascii_repr(s):
    result = '"'
    for ch in s:
        code = ord(ch)
        if ch == '\\':
            result += '\\\\'
        elif ch == '"':
            result += '\\"'
        elif ch == '\n':
            result += '\\n'
        elif ch == '\r':
            result += '\\r'
        elif ch == '\t':
            result += '\\t'
        elif ch == '\b':
            result += '\\b'
        elif ch == '\f':
            result += '\\f'
        elif ch == '\v':
            result += '\\v'
        elif ch == '\0':
            result += '\\0'
        elif 32 <= code < 127:
            result += ch
        else:
            # For non-ASCII characters, represent as \xNN or \uNNNN as repr does
            # CPython's repr uses the shortest escape: \xNN for single byte, \uNNNN for unicode
            if code <= 255:
                result += '\\x' + format(code, '02x')
            else:
                result += '\\u' + format(code, '04x')
    result += '"'
    return result

