def repr_string(s):
    """Produce a Python repr of the string s, mimicking CPython's repr for strings."""
    if not s:
        return "''"
    has_single = "'" in s
    has_double = '"' in s
    use_single = not has_single or has_double
    quote = "'" if use_single else '"'
    parts = [quote]
    for c in s:
        cp = ord(c)
        if cp == 10:
            parts.append('\\n')
        elif cp == 13:
            parts.append('\\r')
        elif cp == 9:
            parts.append('\\t')
        elif cp == quote:
            parts.append('\\' + quote)
        elif cp == 92:
            parts.append('\\\\')
        elif cp < 32 or cp == 127:
            parts.append('\\x%02x' % cp)
        elif cp > 126:
            if cp <= 0xFFFF:
                parts.append('\\u%04x' % cp)
            elif cp <= 0x10FFFF:
                parts.append('\\U%08x' % cp)
            else:
                # Should not happen for valid Unicode
                parts.append(c)
        else:
            parts.append(c)
    parts.append(quote)
    return ''.join(parts)

