    if o == 92:
        return "\\\\"
    if o == 34:
        return "\\\""
    if o == 39:
        return "\\'"
    if 0x20 <= o <= 0x7e:
        return c
    if o < 256:
        return "\\x%02x" % o
    return "\\u%04x" % o

