import os, subprocess, sys, tempfile, threading, time, socket, struct, json

class Server:
    def __init__(self, sock_path):
        self.sock_path = sock_path
        self._sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        self._sock.bind(sock_path)
        self._sock.listen(5)
        self._running = True
        self._workers = {}

    def warm(self):
        pass  # No-op for compatibility

    def open(self):
        pass  # No-op for compatibility

    def serve_forever(self):
        while self._running:
            try:
                conn, _ = self._sock.accept()
                threading.Thread(target=self._handle_conn, args=(conn,), daemon=True).start()
            except OSError:
                break
            except Exception:
                break

    def _handle_conn(self, conn):
        try:
            while self._running:
                data = self._recv_all(conn)
                if not data:
                    break
                try:
                    msg = json.loads(data.decode('utf-8'))
                except Exception:
                    break
                code = msg.get('code', '')
                cwd = msg.get('cwd', None)
                result = subprocess.run(
                    [sys.executable, '-c', code],
                    capture_output=True, text=True, cwd=cwd,
                    stdin=subprocess.DEVNULL
                )
                resp = json.dumps({
                    'returncode': result.returncode,
                    'stdout': result.stdout,
                    'stderr': result.stderr
                }).encode('utf-8')
                conn.sendall(struct.pack('>I', len(resp)) + resp)
        except Exception:
            pass
        finally:
            conn.close()

    def _recv_all(self, conn):
        try:
            header = self._recv_exact(conn, 4)
            if not header:
                return b''
            length = struct.unpack('>I', header)[0]
            if length == 0:
                return b''
            return self._recv_exact(conn, length)
        except Exception:
            return b''

    def _recv_exact(self, conn, n):
        buf = b''
        while len(buf) < n:
            try:
                chunk = conn.recv(n - len(buf))
                if not chunk:
                    return None
                buf += chunk
            except Exception:
                return None
        return buf

    def shutdown(self):
        self._running = False
        try:
            self._sock.close()
        except:
            pass


class Client:
    def __init__(self, sock_path):
        self.sock_path = sock_path
        self._sock = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        self._sock.connect(sock_path)

    def run(self, code, cwd=None):
        msg = json.dumps({'code': code, 'cwd': cwd}).encode('utf-8')
        self._sock.sendall(struct.pack('>I', len(msg)) + msg)

        header = self._recv_exact(4)
        if not header:
            return {'returncode': -1, 'stdout': '', 'stderr': 'connection closed'}
        length = struct.unpack('>I', header)[0]
        data = self._recv_exact(length)
        if not data:
            return {'returncode': -1, 'stdout': '', 'stderr': 'connection closed'}
        result = json.loads(data.decode('utf-8'))
        return result

    def _recv_exact(self, n):
        buf = b''
        while len(buf) < n:
            chunk = self._sock.recv(n - len(buf))
            if not chunk:
                return None
            buf += chunk
        return buf

    def shutdown(self):
        try:
            self._sock.close()
        except:
            pass


