def copysign(mag, sign_ref):
    # mag is the magnitude (could be 0.0 or -0.0, but we want magnitude)
    # We want result with sign of sign_ref and magnitude of mag
    if mag == 0.0:
        # Need to return ±0.0 based on sign_ref
        # sign of sign_ref: check 1/sign_ref
        if 1.0 / sign_ref > 0:
            return 0.0
        else:
            return -0.0
    if sign_ref > 0:
        return mag if mag > 0 else -mag  # ensure positive
    else:
        return -mag if mag > 0 else mag  # ensure negative

import struct

def math_fmod(x, y):
    # fmod(x, y): remainder of x/y with same sign as x
    if y == 0.0:
        raise ValueError("fmod(x, 0.0)")
    if x != x:
        raise ValueError("math domain error")
    if y != y:
        raise ValueError("math domain error")
    if x in (float('inf'), float('-inf')):
        raise ValueError("math domain error")
    if y in (float('inf'), float('-inf')):
        # fmod(x, inf) = x for finite x
        return x
    # General case
    # fmod(x, y) = x - floor(x/y) * y
    # But we need to be careful with floating point
    # Use the standard approach:
    q = x / y
    if q != q:
        raise ValueError("math domain error")
    # Need floor
    if q == q:
        # floor
        import math as _m
        # Actually we can't import. Let's compute floor differently.
        # For a float q, floor(q):
        if q >= 0:
            q_int = int(q)
            if q_int == q:
                return x - q * y
            # Check if int(q) <= q
            return x - q_int * y if q_int <= q else x - (q_int) * y
        else:
            q_int = int(q)  # truncates toward zero
            if q_int == q:
                return x - q_int * y
            # For negative, floor is less or equal
            # int() truncates toward zero, so for negative, int(q) > q (closer to zero)
            # floor(q) = int(q) - 1 if int(q) != q
            floor_q = q_int if q_int == q else q_int - 1
            return x - floor_q * y
    return x

def math_copysign(x, y):
    # Returns a float with the magnitude of x and the sign of y
    x = float(x)
    y = float(y)
    # If y is zero, its sign bit determines the sign
    sx = 1 if (struct.pack('!d', x)[6] & 0x80) else 0
    sy = 1 if (struct.pack('!d', y)[6] & 0x80) else 0
    if x == 0.0 and y != 0.0:
        # result is 0 with sign of y
        return 0.0 if sy == 0 else -0.0
    if y == 0.0:
        # sign of y (could be +0 or -0)
        return 0.0 if sy == 0 else -0.0
    # For normal numbers
    if x == float('inf') or x == float('-inf'):
        return float('inf') if sy == 0 else float('-inf')
    if x != x:
        return float('nan')
    # For finite nonzero x
    # We need to flip the sign if sx != sy
    if sx == sy:
        return x
    else:
        return -x

def math_floor(x):
    # Floor of x as a float
    if x != x:
        raise ValueError("math domain error")
    if x in (float('inf'), float('-inf')):
        return x
    if x >= 0:
        i = int(x)
        # i is floor if i == x or i < x
        # For positive, int(x) <= x always (truncation toward zero)
        # But due to floating point, int(x) could be > x? No.
        return float(i) if i == x else float(i)
    else:
        i = int(x)  # truncates toward zero, so i >= x
        if i == x:
            return float(i)
        else:
            return float(i - 1)

def cpython_style(x, y):
    """The else-branch algorithm, run in Python, with NO is_finite guard."""
    mod = math_fmod(x, y)
    div = (x - mod) / y
    if mod != 0.0 and (mod < 0.0) != (y < 0.0):
        div -= 1.0
    if div == 0.0:
        return math_copysign(0.0, x/y)
    fd = math_floor(div)
    return fd + 1.0 if div - fd > 0.5 else fd

