def isnan(v):
    return v != v

def isinf(v):
    return v == float('inf') or v == float('-inf')

def copysign(a, b):
    # return a with the sign of b
    if a == 0.0:
        # distinguish +0.0 and -0.0
        # We need to return 0.0 or -0.0
        if b < 0.0 or (b == 0.0 and _is_negzero(b)):
            return -0.0
        else:
            return 0.0
    if b >= 0.0:
        return abs(a)
    else:
        return -abs(a)

def _is_negzero(v):
    return v == 0.0 and hex(v) == '-0x0.0p+0'

def fmod(x, y):
    # Python's % does not do fmod, but we can use the formula:
    # fmod(x, y) = x - floor(x/y)*y  but that has issues with inf/nan
    # Actually, Python's % operator gives a different result than fmod.
    # fmod: result has same sign as x
    # Python %: result has same sign as y
    # So: fmod(x,y) = x - (x//y)*y doesn't work directly for our purpose
    # Let's compute it properly:
    # For finite x and y:
    # fmod(x, y) = x - round(x/y)*y  (truncated division)
    # Actually, fmod uses truncation toward zero.
    if isnan(x) or isnan(y):
        return float('nan')
    if isinf(x):
        return float('nan')
    if isinf(y):
        return x
    if y == 0.0:
        return float('nan')
    # Use the formula: fmod(x, y) = x - int(x/y) * y, but x/y might overflow
    # Better: 
    q = int(x / y) if not isinf(x / y) else 0
    # But x/y might be inf or have precision issues
    # Let's use: fmod = x - trunc(x/y) * y
    # We need trunc(x/y):
    ratio = x / y
    if isnan(ratio) or isinf(ratio):
        return x  # if ratio is inf, that means y is very small relative to x, fmod is x
    # trunc toward zero
    if ratio > 0:
        trunc_ratio = int(ratio)
    else:
        trunc_ratio = -int(-ratio)
    result = x - trunc_ratio * y
    return result

def ffloor(v):
    """Rust f64::floor: total, returns a float, inf->inf, nan->nan."""
    if isnan(v) or isinf(v):
        return v
    # floor toward -inf
    if v >= 0:
        return float(int(v))
    else:
        iv = int(v)
        if iv == v:
            return float(iv)
        return float(iv - 1)

