def _int_part(v):
    """Return (int_part, frac) for a finite float.
    frac is the float residual v - int_part (so v == int_part + frac)."""
    ip = int(v)
    return ip, v - ip

def ffloor(v):
    """Rust f64::floor: total, returns a float, inf->inf, nan->nan."""
    if v != v:            # NaN
        return v
    if v == float('inf'):
        return float('inf')
    if v == float('-inf'):
        return float('-inf')
    # Finite case
    ip, frac = _int_part(v)
    # frac is in (-1, 1) for floats representable as int + frac
    # math.floor = largest int <= v
    if frac >= 0:
        fl = ip
    else:
        fl = ip - 1
    return float(fl)

def fmod(x, y):
    """Python math.fmod: x - n*y where n = trunc(x/y).
    Returns float('nan') if x is inf or NaN."""
    if x != x:
        return float('nan')
    if x == float('inf') or x == float('-inf'):
        return float('nan')
    # n = trunc(x / y)
    q = x / y
    # Truncate q towards zero
    ip, frac = _int_part(q)
    # q is finite (x, y finite and nonzero => q finite unless overflow)
    # If y is very small, x/y may be inf — but then mod is effectively 0 or x
    # Handle inf q: that means |x/y| > MAX_DOUBLE, so n*y wraps; fmod = x in that case
    if q == float('inf'):
        return x
    if q == float('-inf'):
        return x
    n = ip  # truncated integer part
    r = x - n * y
    return r

