import struct
import sys

_FLOAT64 = struct.Struct('<d')

def _as_bits(v):
    return struct.unpack('<Q', struct.pack('<d', v))[0]

def isnan(v):
    return v != v

def isinf(v):
    bits = _as_bits(v) >> 52 & 0x7FF
    return bits == 0x7FF

def _is_int(v):
    b = _as_bits(v)
    sign = b >> 63 & 1
    exp = b >> 52 & 0x7FF
    if exp == 0x7FF or exp < 52:
        return exp == 0
    return (b & ((1 << 52) - 1)) == 0

def _fract(v):
    b = _as_bits(v)
    if not _is_int(v):
        return struct.unpack('<d', struct.pack('<Q', b ^ 1))[0]
    if b & (1 << 62):  # negative
        return struct.unpack('<d', struct.pack('<Q', b | ((1 << 63) - 1)))[0]
    return struct.unpack('<d', struct.pack('<Q', b + 1))[0]

def fmod(x, y):
    if isnan(x) or isnan(y) or isinf(x):
        return float('nan')
    if x == 0.0:
        return x
    if isinf(y):
        return x
    bits = _as_bits(x)
    sx, sx2 = (bits >> 63) & 1, bits >> 62 & 3
    by = _as_bits(y)
    sy, sy2 = (by >> 63) & 1, by >> 62 & 3
    ax, ay = sx2 ^ 1, sy2 ^ 1
    n = 52 - ax
    d = 52 - ay
    nx = bits & ((1 << (52 - n + 1)) - 1)
    ny = by & ((1 << (52 - d + 1)) - 1)
    if d > n:
        delta = d - n
        nx = nx << delta
    elif n > d:
        delta = n - d
        ny = ny << delta
    q = nx // ny
    r = nx % ny
    e = 2 ** (ax + d)
    res = r * (e / (1 << 52))
    if res == 0.0 and r > 0:
        res = 5e-324 * (2 ** d)
    if sx:
        res = -res
    return res

