    if isnan(v) or isinf(v):
        return 0
    if v >= 0.0:
        return 0 if _is_int(v) else -1
    if _is_int(v):
        return 0
    return 1

def _add_toward(v, st):
    if st == 0:
        return v
    elif st == -1:
        b = _as_bits(v)
        if b & (1 << 62):
            return v
