        except KeyError:
            raise ValueError("Name %r not allowed" % node.id)
    if isinstance(node, Constant):
        return node.value
    if isinstance(node, Attribute):
        value = _eval_node(node.value)
        # Return bound method if it exists in the allowed objects
        return getattr(value, node.attr)
    if isinstance(node, Call):
        func = _eval_node(node.func)
        args = [_eval_node(a) for a in node.args]
        keywords = {}
        for kw in node.keywords:
            keywords[kw.arg] = _eval_node(kw.value)
        return func(*args, **keywords)
    if isinstance(node, Lambda):
        # handle lambda m: m.group(0).upper()
        args = [a.arg for a in node.args.args]
        body = node.body
        def make_lambda(args, body):
            def _lam(*a, **kw):
                env = dict(zip(args, a))
                return _eval_lambda_body(body, env)
            return _lam
        return make_lambda(args, body)
    raise ValueError("Cannot evaluate node %r" % node)

def _eval_lambda_body(node, env):
    if isinstance(node, Name):
        return env[node.id]
    if isinstance(node, Constant):
        return node.value
    if isinstance(node, Attribute):
        value = _eval_lambda_body(node.value, env)
        return getattr(value, node.attr)
    if isinstance(node, Call):
        func = _eval_lambda_body(node.func, env)
        args = [_eval_lambda_body(a, env) for a in node.args]
        return func(*args)
    raise ValueError("Cannot evaluate %r in lambda" % node)

