# Define a helper to create dict_keys-like object with matching repr/str/type name
class FakeDictKeys:
    def __init__(self, d):
        self._d = d
    def __repr__(self):
        return "dict_keys({{}})".format(", ".join(repr(k) for k in self._d))
    def __str__(self):
        return self.__repr__()
    def __iter__(self):
        return iter(self._d)
    def __len__(self):
        return len(self._d)
    def __eq__(self, other):
        return list(self._d) == list(other)
    def __hash__(self):
        raise TypeError("unhashable type: 'FakeDictKeys'")

class FakeDictValues:
    def __init__(self, d):
        self._d = d
    def __repr__(self):
        return "dict_values({{}})".format(", ".join(repr(v) for v in self._d.values()))
    def __str__(self):
        return self.__repr__()
    def __iter__(self):
        return iter(self._d.values())
    def __len__(self):
        return len(self._d)
    def __eq__(self, other):
        return list(self._d.values()) == list(other)
    def __hash__(self):
        raise TypeError("unhashable type: 'FakeDictValues'")

class FakeDictItems:
    def __init__(self, d):
        self._d = d
    def __repr__(self):
        return "dict_items({{}})".format(", ".join(repr((k, v)) for k, v in self._d.items()))
